import React, { useState, useRef, useEffect, useCallback } from "react";


const CAMERA_SRC = "data:image/png;base64,";
const FRAME_SRC = "data:image/png;base64,";

// Aesthetic filter presets — CSS filter strings, applied live + baked into the photo
const FILTERS = [
  { id: "none", label: "None", css: "none" },
  { id: "classic", label: "Classic", css: "contrast(1.05) saturate(1.15) sepia(0.08)" },
  { id: "warm", label: "Warm", css: "sepia(0.35) saturate(1.3) brightness(1.05) contrast(1.02)" },
  { id: "cool", label: "Cool", css: "saturate(1.1) hue-rotate(-12deg) brightness(1.03) contrast(1.05)" },
  { id: "mono", label: "B&W", css: "grayscale(1) contrast(1.1) brightness(1.02)" },
  { id: "faded", label: "Faded", css: "contrast(0.9) saturate(0.8) brightness(1.08) sepia(0.12)" },
  { id: "vivid", label: "Vivid", css: "saturate(1.5) contrast(1.15)" },
];
const DEVELOP_MS = 4200;

// ---- sound effects (reproduced from reference utils/soundEffects.ts) ----
function playShutter() {
  try {
    const a = new Audio("https://cdn.pixabay.com/download/audio/2022/03/15/audio_4affbf5b9e.mp3?filename=camera-shutter-6305.mp3");
    a.volume = 0.7; a.play().catch(() => {});
  } catch (e) {}
}
function playSlide() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const size = ctx.sampleRate * 1.5;
    const buf = ctx.createBuffer(1, size, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < size; i++) {
      const env = Math.sin((i / size) * Math.PI);
      d[i] = (Math.random() * 2 - 1) * env * 0.35;
    }
    const src = ctx.createBufferSource(); src.buffer = buf;
    const flt = ctx.createBiquadFilter(); flt.type = "lowpass";
    flt.frequency.setValueAtTime(800, ctx.currentTime);
    flt.frequency.linearRampToValueAtTime(300, ctx.currentTime + 1);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.5, ctx.currentTime);
    g.gain.linearRampToValueAtTime(0.3, ctx.currentTime + 1.5);
    src.connect(flt); flt.connect(g); g.connect(ctx.destination);
    src.start(ctx.currentTime);
  } catch (e) {}
}
function playBeep() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator(); const g = ctx.createGain();
    osc.connect(g); g.connect(ctx.destination);
    osc.frequency.setValueAtTime(800, ctx.currentTime); osc.type = "sine";
    g.gain.setValueAtTime(0, ctx.currentTime);
    g.gain.linearRampToValueAtTime(0.3, ctx.currentTime + 0.05);
    g.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.2);
    osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.2);
  } catch (e) {}
}

function FilterThumb({ videoRef, f, active, onPick }) {
  const ref = React.useRef(null);
  React.useEffect(() => {
    let raf;
    const draw = () => {
      const cv = ref.current, v = videoRef.current;
      if (cv && v && v.videoWidth) {
        const ctx = cv.getContext("2d");
        const size = Math.min(v.videoWidth, v.videoHeight);
        const sx = (v.videoWidth - size) / 2, sy = (v.videoHeight - size) / 2;
        ctx.save();
        ctx.filter = f.css === "none" ? "none" : f.css;
        ctx.translate(cv.width, 0); ctx.scale(-1, 1); // mirror
        ctx.drawImage(v, sx, sy, size, size, 0, 0, cv.width, cv.height);
        ctx.restore();
      }
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf);
  }, [f, videoRef]);
  return (
    <div onClick={onPick} style={{ flex: "0 0 auto", cursor: "pointer", textAlign: "center" }}>
      <canvas ref={ref} width={96} height={96}
        style={{ width: 52, height: 52, borderRadius: "50%", objectFit: "cover",
          border: active ? "3px solid #fff" : "3px solid rgba(255,255,255,0.35)",
          boxShadow: active ? "0 0 0 2px #341d16" : "none" }} />
      <div style={{ color: "#fff", fontSize: 10, marginTop: 4, fontWeight: 700, opacity: active ? 1 : 0.7 }}>{f.label}</div>
    </div>
  );
}

export default function InstantMemoryMaker() {
  const [state, setState] = useState("idle"); // idle | camera | captured
  const [filter, setFilter] = useState(FILTERS[0]);
  const [captured, setCaptured] = useState(null);
  const [countdown, setCountdown] = useState(null);
  const [showFlash, setShowFlash] = useState(false);
  const [developing, setDeveloping] = useState(false);
  const [note, setNote] = useState("");
  const [caption, setCaption] = useState("");
  const [noteDone, setNoteDone] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileRef = useRef(null);
  const streamRef = useRef(null);

  const stopStream = useCallback(() => {
    if (streamRef.current) { streamRef.current.getTracks().forEach((t) => t.stop()); streamRef.current = null; }
  }, []);
  useEffect(() => () => stopStream(), [stopStream]);

  const startCamera = useCallback(async () => {
    setNote("");
    setState("camera");
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 1280 } }, audio: false });
      streamRef.current = s;
      await new Promise((r) => setTimeout(r, 100));
      if (videoRef.current) { videoRef.current.srcObject = s; await videoRef.current.play().catch(() => {}); }
    } catch (e) {
      setNote("Camera blocked here — close and use Upload or Sample.");
    }
  }, []);

  const stopCamera = useCallback(() => { stopStream(); setState("idle"); setCountdown(null); }, [stopStream]);

  // square crop (fits the classic Polaroid square window); bakes in the chosen filter
  const cropFrom = useCallback((source, sw, sh, mirror, filterCss) => {
    const size = Math.min(sw, sh), sx = (sw - size) / 2, sy = (sh - size) / 2;
    const c = canvasRef.current; const OUT = 900; c.width = OUT; c.height = OUT;
    const ctx = c.getContext("2d");
    if (filterCss && filterCss !== "none") ctx.filter = filterCss;
    if (mirror) { ctx.translate(OUT, 0); ctx.scale(-1, 1); }
    ctx.drawImage(source, sx, sy, size, size, 0, 0, OUT, OUT);
    ctx.filter = "none";
    return c.toDataURL("image/jpeg", 0.92);
  }, []);

  const beginDevelop = useCallback((src) => {
    setCaptured(src);
    setState("captured");
    setDeveloping(true);
    setShowFlash(true);
    playShutter();
    setTimeout(() => setShowFlash(false), 400);
    setTimeout(() => playSlide(), 300);
    requestAnimationFrame(() => setTimeout(() => setDeveloping(false), 60));
  }, []);

  const capturePhoto = useCallback(() => {
    const v = videoRef.current;
    if (!v || !v.videoWidth) { setNote("No camera frame. Use Upload or Sample."); return; }
    const src = cropFrom(v, v.videoWidth, v.videoHeight, true, filter.css);
    stopStream();
    beginDevelop(src);
  }, [cropFrom, stopStream, beginDevelop, filter]);

  const startCountdown = useCallback(() => {
    setCountdown(3); playBeep();
    setTimeout(() => { setCountdown(2); playBeep(); }, 1000);
    setTimeout(() => { setCountdown(1); playBeep(); }, 2000);
    setTimeout(() => { setCountdown(null); capturePhoto(); }, 3000);
  }, [capturePhoto]);

  const handleUpload = useCallback((e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setNote("Reading " + file.name + "...");
    const reader = new FileReader();
    reader.onerror = () => setNote("Couldn't read that file.");
    reader.onload = () => {
      const img = new Image();
      img.onload = () => { setNote(""); beginDevelop(cropFrom(img, img.naturalWidth, img.naturalHeight, false, filter.css)); };
      img.onerror = () => setNote("Try a JPG or simpler PNG.");
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
    e.target.value = "";
  }, [cropFrom, beginDevelop, filter]);

  const loadSample = useCallback(() => {
    const c = canvasRef.current; const OUT = 900; c.width = OUT; c.height = OUT;
    const ctx = c.getContext("2d");
    if (filter.css && filter.css !== "none") ctx.filter = filter.css;
    const g = ctx.createLinearGradient(0, 0, OUT, OUT);
    g.addColorStop(0, "#ffd08a"); g.addColorStop(0.5, "#ff8fb1"); g.addColorStop(1, "#9b7fe0");
    ctx.fillStyle = g; ctx.fillRect(0, 0, OUT, OUT);
    ctx.fillStyle = "rgba(255,255,255,0.85)"; ctx.beginPath(); ctx.arc(640, 260, 96, 0, Math.PI * 2); ctx.fill();
    ctx.filter = "none";
    beginDevelop(c.toDataURL("image/jpeg", 0.92));
  }, [beginDevelop, filter]);

  const downloadPhoto = useCallback(() => {
    if (!captured) return;
    const c = document.createElement("canvas");
    // Compose: draw the square photo, then overlay the frame PNG on top.
    const frame = new Image();
    frame.onload = () => {
      const FW = frame.naturalWidth, FH = frame.naturalHeight;
      c.width = FW; c.height = FH;
      const ctx = c.getContext("2d");
      const img = new Image();
      img.onload = () => {
        // window rect in frame px (from measured %)
        const wx = 0.091 * FW, wy = 0.089 * FH, ww = 0.814 * FW, wh = 0.679 * FH;
        //ctx.fillStyle = "#000"; ctx.fillRect(wx, wy, ww, wh);
        // cover-fit the square photo into the window
        const ar = img.width / img.height, war = ww / wh;
        let dw, dh, dx, dy;
        if (ar > war) { dh = wh; dw = wh * ar; dx = wx + (ww - dw) / 2; dy = wy; }
        else { dw = ww; dh = ww / ar; dx = wx; dy = wy + (wh - dh) / 2; }
        ctx.save(); ctx.beginPath(); ctx.rect(wx - 2, wy - 2, ww + 4, wh + 4); ctx.clip();
        ctx.drawImage(img, dx - 2, dy - 2, dw + 4, dh + 4); ctx.restore();
        ctx.drawImage(frame, 0, 0, FW, FH);
        c.toBlob((b) => {
          if (!b) return;
          const url = URL.createObjectURL(b);
          const a = document.createElement("a");
          a.href = url; a.download = "polaroid-" + Date.now() + ".png";
          document.body.appendChild(a); a.click(); document.body.removeChild(a);
          URL.revokeObjectURL(url);
        }, "image/png", 1.0);
      };
      img.src = captured;
    };
    frame.src = FRAME_SRC;
  }, [captured]);

  const reset = useCallback(() => { setCaptured(null); setState("idle"); setDeveloping(false); setNote(""); setCaption(""); setNoteDone(false); }, []);

  return (
    <div style={{ minHeight: "100vh", background: "linear-gradient(180deg,#ece4db 0%,#efe8e0 50%,#f1ece5 100%)", position: "relative", display: "flex", flexDirection: "column", alignItems: "center", padding: "6vh 20px 80px", fontFamily: "'Bricolage Grotesque',-apple-system,sans-serif", boxSizing: "border-box" }}>
      <style>{CSS}</style>
      {showFlash && <div className="fullflash" />}

      <div className="fadeDown" style={{ textAlign: "center", marginBottom: 110 }}>
        <h1 style={{ fontFamily: "'Syne',sans-serif", fontSize: "clamp(48px,9vw,88px)", fontWeight: 800, color: "#1f2937", margin: 0, letterSpacing: "-0.03em" }}>Snapit</h1>
      </div>

      {/* idle */}
      {state === "idle" && (
        <div className="pop" style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <img src={CAMERA_SRC} alt="Instax Mini 12" onClick={startCamera} draggable={false}
            style={{ width: "min(320px,78vw)", cursor: "pointer", filter: "drop-shadow(0 24px 40px rgba(90,70,140,0.28))" }}
            className="hoverScale" />
          <div style={{ display: "flex", gap: 16, marginTop: 28 }}>
            <button style={BTN.cta} onClick={startCamera}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
              Camera
            </button>
            <button style={BTN.cta} onClick={() => fileRef.current && fileRef.current.click()}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>
              Upload
            </button>
          </div>
          {note && <p style={{ color: "#6b7280", fontSize: 13, marginTop: 12 }}>{note}</p>}
        </div>
      )}

      {/* camera modal */}
      {state === "camera" && (
        <div className="fadeUp" style={{ width: "100%", maxWidth: 420 }}>
          <div style={{ background: "#fff", padding: 16, borderRadius: 26, boxShadow: "0 20px 60px rgba(0,0,0,0.25)" }}>
            <div style={{ position: "relative", borderRadius: 16, overflow: "hidden", background: "#000", aspectRatio: "4/5" }}>
              <video ref={videoRef} autoPlay playsInline muted style={{ width: "100%", height: "100%", objectFit: "cover", transform: "scaleX(-1)", filter: filter.css }} />
              {countdown !== null && (
                <div className="countWrap" style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "rgba(0,0,0,0.5)" }}>
                  <div key={countdown} className="countNum" style={{ color: "#fff", fontWeight: 700, fontSize: 120, textShadow: "0 4px 20px rgba(0,0,0,0.5)" }}>{countdown}</div>
                </div>
              )}
              <button onClick={stopCamera} aria-label="Close" style={{ position: "absolute", top: 14, right: 14, width: 40, height: 40, borderRadius: "50%", border: "none", background: "rgba(0,0,0,0.5)", color: "#fff", fontSize: 20, cursor: "pointer" }}>×</button>
              {note && <div style={{ position: "absolute", bottom: 12, left: 12, right: 12, textAlign: "center", color: "#fff", fontSize: 13, background: "rgba(0,0,0,0.45)", padding: 8, borderRadius: 8 }}>{note}</div>}

              {/* live filter previews along the bottom of the feed */}
              {countdown === null && (
                <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, display: "flex", gap: 10, padding: "10px 12px 12px", overflowX: "auto", background: "linear-gradient(transparent, rgba(0,0,0,0.45))" }}>
                  {FILTERS.map((f) => (
                    <FilterThumb key={f.id} videoRef={videoRef} f={f} active={filter.id === f.id} onPick={() => setFilter(f)} />
                  ))}
                </div>
              )}
            </div>
            <button onClick={startCountdown} disabled={countdown !== null}
              style={{ ...BTN.wide, background: countdown !== null ? "#b3a898" : "#8a7a68", marginTop: 16 }}>
              {countdown !== null ? "Capturing in " + countdown + "..." : "Capture Photo"}
            </button>
          </div>
        </div>
      )}

      {/* captured */}
      {state === "captured" && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: "100%", maxWidth: 420, position: "relative" }}>
          {!developing && !noteDone && <p style={{ color: "#8a7a68", fontSize: 18, margin: "0 0 12px", fontFamily: "'Caveat',cursive" }}>add a note?</p>}
          <div style={{ position: "relative", zIndex: 30 }}>
            <img src={CAMERA_SRC} alt="" style={{ width: "min(320px,78vw)", display: "block", position: "relative", zIndex: 30, filter: "drop-shadow(0 24px 40px rgba(90,70,140,0.28))" }} />
            <div style={{ display: "flex", justifyContent: "center", marginTop: "-14%", position: "relative", zIndex: 10 }}>
              {captured && (
                <div className="slideOut" style={{ width: "min(240px,62vw)", position: "relative" }}>
                  {/* photo sits inside the frame's black window: left 9.1% top 8.9% w 81.4% h 67.9% */}
                  <div style={{ position: "absolute", left: "9.1%", top: "8.9%", width: "81.4%", height: "67.9%", overflow: "hidden", background: "#0a0a0a" }}>
                    <img src={captured} alt="" className={developing ? "developing" : "developed"} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                    <div className={developing ? "chem developing" : "chem developed"} style={{ position: "absolute", inset: 0, background: "#ece7dd", pointerEvents: "none" }} />
                  </div>
                  <img src={FRAME_SRC} alt="" style={{ width: "100%", display: "block", position: "relative", pointerEvents: "none", filter: "drop-shadow(0 18px 30px rgba(60,50,90,0.22))" }} draggable={false} />
                  {caption && !developing && (
                    <div style={{ position: "absolute", left: "9%", right: "9%", top: "80%", textAlign: "center", fontFamily: "'Caveat',cursive", fontSize: "clamp(18px,5vw,26px)", color: "#2a2a2a", pointerEvents: "none" }}>{caption}</div>
                  )}
                </div>
              )}
            </div>
          </div>

          {!developing && !noteDone && (
            <div className="fadeLate" style={{ display: "flex", flexDirection: "column", alignItems: "center", width: "100%", maxWidth: 360, padding: "0 16px", marginTop: 22 }}>
              <input
                type="text"
                value={caption}
                maxLength={40}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="write something..."
                style={{ width: "100%", textAlign: "center", border: "none", borderBottom: "1.5px solid #cdbfae", background: "transparent", outline: "none", fontFamily: "'Caveat',cursive", fontSize: 24, color: "#4b3f33", padding: "6px 0" }}
              />
              <div style={{ fontSize: 12, color: "#a99", marginTop: 6 }}>{caption.length}/40</div>
              <button onClick={() => setNoteDone(true)} style={{ ...BTN.wide, background: "#8a7a68", marginTop: 16, maxWidth: 220 }}>Done</button>
            </div>
          )}
          {noteDone && (
            <div className="fadeLate" style={{ display: "flex", gap: 12, marginTop: 22, width: "100%", maxWidth: 360, padding: "0 16px" }}>
              <button onClick={downloadPhoto} style={{ ...BTN.cta, justifyContent: "center", flex: 1, background: "#8a7a68", color: "#fff", border: "none" }}>
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                Download
              </button>
              <button onClick={reset} style={{ ...BTN.cta, justifyContent: "center", flex: 1 }}>
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
                New Photo
              </button>
            </div>
          )}
        </div>
      )}



      <input ref={fileRef} type="file" accept="image/*" onChange={handleUpload} style={{ display: "none" }} />
      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
}

const BTN = {
  ghost: { padding: "12px 22px", borderRadius: 999, border: "1px solid #d6cfe6", background: "#fff", color: "#1f2937", fontSize: 15, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" },
  cta: { display: "flex", alignItems: "center", justifyContent: "center", gap: 8, padding: "11px 22px", borderRadius: 999, border: "1.5px solid #c3bbb0", background: "#fff", color: "#6b5f52", fontSize: 16, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", whiteSpace: "nowrap", lineHeight: 1 },
  wide: { width: "100%", padding: "16px", borderRadius: 999, border: "none", color: "#fff", fontSize: 17, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", boxShadow: "0 8px 20px rgba(71, 43, 26, 0.3)" },
  flex: { flex: 1, padding: "13px", borderRadius: 999, border: "none", fontSize: 15, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", boxShadow: "0 6px 16px rgba(0,0,0,0.12)" },
};

const CSS = "\
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@300;400;700&family=Caveat:wght@400;700&family=Syne:wght@600;700;800&display=swap');\
@keyframes slideOut{0%{transform:translateY(-78%);opacity:0}100%{transform:translateY(0);opacity:1}}\
.slideOut{animation:slideOut 2s cubic-bezier(.22,1,.36,1) .3s both}\
@keyframes fullflash{0%{opacity:0}30%{opacity:1}100%{opacity:0}}\
.fullflash{position:fixed;inset:0;background:#fff;z-index:60;pointer-events:none;animation:fullflash .4s ease-out forwards}\
@keyframes countPop{0%{transform:scale(.5);opacity:0}40%{transform:scale(1);opacity:1}100%{transform:scale(1.5);opacity:0}}\
.countNum{animation:countPop 1s ease-out}\
.developing{filter:saturate(.15) brightness(1.5) contrast(.7) hue-rotate(-12deg);opacity:.4}\
.developed{filter:none;opacity:1;transition:filter " + DEVELOP_MS + "ms cubic-bezier(.22,1,.36,1),opacity " + DEVELOP_MS + "ms cubic-bezier(.22,1,.36,1)}\
.chem.developing{opacity:.96}\
.chem.developed{opacity:0;transition:opacity " + DEVELOP_MS + "ms cubic-bezier(.33,1,.68,1)}\
@keyframes fadeDown{from{opacity:0;transform:translateY(-20px)}to{opacity:1;transform:none}}\
.fadeDown{animation:fadeDown .6s ease both}\
@keyframes fadeUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}\
.fadeUp{animation:fadeUp .4s ease both}\
@keyframes pop{from{opacity:0;transform:scale(.9)}to{opacity:1;transform:none}}\
.pop{animation:pop .5s ease both}\
.hoverScale{transition:transform .2s}.hoverScale:hover{transform:scale(1.03)}\
.fadeLate{animation:fadeUp .5s ease 0.2s both}\
.fadeLate2{animation:fadeUp .5s ease 0.2s both}\
@media(prefers-reduced-motion:reduce){.slideOut,.countNum,.fadeDown,.fadeUp,.pop,.fadeLate,.fadeLate2{animation-duration:.01ms!important}.developed,.chem.developed{transition-duration:300ms}}\
";
